import {test} from 'node:test'; import a from 'node:assert';
import {BoNhoLRU as C} from './sol.ts';
const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
test('loai it dung nhat',()=>{const c=new C(2,10000);c.dat('a',1);c.dat('b',2);c.lay('a');c.dat('c',3);a.strictEqual(c.lay('b'),undefined);a.strictEqual(c.lay('a'),1);a.strictEqual(c.lay('c'),3);});
test('lay KHONG lam moi han',async()=>{const c=new C(5,120);c.dat('a',1);await sleep(70);a.strictEqual(c.lay('a'),1);await sleep(70);a.strictEqual(c.lay('a'),undefined);});
test('dat lai LAM MOI han',async()=>{const c=new C(5,120);c.dat('a',1);await sleep(70);c.dat('a',9);await sleep(70);a.strictEqual(c.lay('a'),9);});
test('co chi dem chua qua han',async()=>{const c=new C(5,60);c.dat('a',1);c.dat('b',2);a.strictEqual(c.co(),2);await sleep(90);a.strictEqual(c.co(),0);});

import {test} from 'node:test'; import a from 'node:assert';
import {gopKhoang as f} from './sol.ts';
test('cham nhau thi gop',()=>{a.deepStrictEqual(f([{dau:1,cuoi:5,dongCuoi:false},{dau:5,cuoi:8,dongCuoi:true}]),[{dau:1,cuoi:8,dongCuoi:true}]);});
test('roi nhau thi khong gop',()=>{a.deepStrictEqual(f([{dau:1,cuoi:5,dongCuoi:false},{dau:6,cuoi:8,dongCuoi:true}]),[{dau:1,cuoi:5,dongCuoi:false},{dau:6,cuoi:8,dongCuoi:true}]);});
test('long nhau',()=>{a.deepStrictEqual(f([{dau:1,cuoi:10,dongCuoi:true},{dau:3,cuoi:4,dongCuoi:true}]),[{dau:1,cuoi:10,dongCuoi:true}]);});
test('khong sap san',()=>{a.deepStrictEqual(f([{dau:9,cuoi:12,dongCuoi:true},{dau:1,cuoi:3,dongCuoi:false},{dau:2,cuoi:9,dongCuoi:false}]),[{dau:1,cuoi:12,dongCuoi:true}]);});
test('mang rong',()=>{a.deepStrictEqual(f([]),[]);});
test('bien mo khong nuot',()=>{a.deepStrictEqual(f([{dau:1,cuoi:5,dongCuoi:false},{dau:5,cuoi:5,dongCuoi:false}]),[{dau:1,cuoi:5,dongCuoi:false}]);});

